"""Heat diffusion on the GPU.

Reads a grid from a text file, applies the stencil
    new = (4 * self + left + right + up + down) // 8
for the requested number of steps on the GPU, and prints the grid and its sum.
"""

import sys
from array import array

import wgpu

WORKGROUP = 8

SHADER = """
struct Params {
    width: u32,
    height: u32,
    pad0: u32,
    pad1: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    let xl = select(x - 1u, 0u, x == 0u);
    let xr = select(x + 1u, params.width - 1u, x + 1u >= params.width);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = select(y + 1u, params.height - 1u, y + 1u >= params.height);

    let w = params.width;
    let self_v = src[y * w + x];
    let left = src[y * w + xl];
    let right = src[y * w + xr];
    let up = src[yu * w + x];
    let down = src[yd * w + x];

    dst[y * w + x] = (4u * self_v + left + right + up + down) / 8u;
}
"""


def read_grid(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, steps = (int(t) for t in tokens[:3])
    values = [int(t) for t in tokens[3:3 + width * height]]
    return width, height, steps, values


def run_steps(width, height, steps, values):
    device = wgpu.gpu.request_adapter_sync(
        power_preference="high-performance"
    ).request_device_sync()

    count = width * height
    nbytes = count * 4
    storage = wgpu.BufferUsage.STORAGE
    copy_src = wgpu.BufferUsage.COPY_SRC
    copy_dst = wgpu.BufferUsage.COPY_DST

    buf_a = device.create_buffer(size=nbytes, usage=storage | copy_src | copy_dst)
    buf_b = device.create_buffer(size=nbytes, usage=storage | copy_src | copy_dst)
    params = device.create_buffer(
        size=16, usage=wgpu.BufferUsage.UNIFORM | copy_dst
    )
    readback = device.create_buffer(
        size=nbytes, usage=wgpu.BufferUsage.MAP_READ | copy_dst
    )

    device.queue.write_buffer(buf_a, 0, array("I", values).tobytes())
    device.queue.write_buffer(params, 0, array("I", [width, height, 0, 0]).tobytes())

    module = device.create_shader_module(code=SHADER)
    layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.read_only_storage},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )
    pipeline = device.create_compute_pipeline(
        layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
        compute={"module": module, "entry_point": "step"},
    )

    def bind_group(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 16}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": nbytes}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": nbytes}},
            ],
        )

    groups = (bind_group(buf_a, buf_b), bind_group(buf_b, buf_a))
    dispatch_x = (width + WORKGROUP - 1) // WORKGROUP
    dispatch_y = (height + WORKGROUP - 1) // WORKGROUP

    # Each step is its own compute pass so the writes of one step are visible
    # to the reads of the next. Steps alternate between the two buffers.
    encoder = device.create_command_encoder()
    for i in range(steps):
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, groups[i % 2])
        compute.dispatch_workgroups(dispatch_x, dispatch_y, 1)
        compute.end()

    final = buf_a if steps % 2 == 0 else buf_b
    encoder.copy_buffer_to_buffer(final, 0, readback, 0, nbytes)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ)
    result = array("I")
    result.frombytes(readback.read_mapped().tobytes())
    readback.unmap()
    return result.tolist()


def main():
    if len(sys.argv) < 2:
        print("usage: main.py <grid-file>", file=sys.stderr)
        return 2

    width, height, steps, values = read_grid(sys.argv[1])

    if steps == 0:
        grid = values
    else:
        grid = run_steps(width, height, steps, values)

    lines = []
    for row in range(height):
        lines.append(" ".join(map(str, grid[row * width:(row + 1) * width])))
    lines.append(f"SUM {sum(grid)}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

